import { MessageChannelFactory, BaseMessageChannel } from '../message-channels';
import { IBootstrapConfigPayload, IChatChildEvents, IChatFontSizePayload, IChatParentEvents, IChatStyle, IRoomConfigPayload, ISendMessagePayload, IChatColourPayload, IWarmBackgroundPayload, IShowLobbyButtonPayload, IActionMenuChatPayload, IShowDemoModePayload, IShowChatClosedOverlayPayload, IPromoRequestPayload } from '../types';

export class ChatProxy implements IChatChildEvents {
    private messageChannel: BaseMessageChannel<IChatChildEvents, IChatParentEvents>;
    private hasReceivedOnInit: boolean;

    constructor(iframe: HTMLIFrameElement) {
        this.messageChannel = MessageChannelFactory.create({ type: 'web', target: iframe, source: 'chat' });
        this.hasReceivedOnInit = false;
        this.messageChannel.waitForResponse('onInit', 'chat').then(() => this.hasReceivedOnInit = true);
    }

    public onLoseFocus(): void {
        this.messageChannel.send('onLoseFocus', void 0);
    }

    public disconnect(): void {
        this.messageChannel.send('disconnect', void 0);
    }

    public async setup(config: IBootstrapConfigPayload) {
        if (!this.hasReceivedOnInit) {
            await this.messageChannel.waitForResponse('onInit', 'chat');
            this.hasReceivedOnInit = true;
        }

        this.messageChannel.send('setup', config);
    }

    public showLobbyButton(payload: IShowLobbyButtonPayload): void {
        this.messageChannel.send('showLobbyButton', payload);
    }

    public sendMessage(payload: ISendMessagePayload): void {
        this.messageChannel.send('sendMessage', payload);
    }

    public setChatColour(payload: IChatColourPayload): void {
        this.messageChannel.send('setChatColour', payload);
    }

    public setChatSize(payload: IChatFontSizePayload): void {
        this.messageChannel.send('setChatSize', payload);
    }

    public setChatStyle(payload: IChatStyle): void {
        this.messageChannel.send('setChatStyle', payload);
    }

    public setDemoMode(payload: IShowDemoModePayload): void {
        this.messageChannel.send('setDemoMode', payload);
    }

    public setWarmBackground(payload: IWarmBackgroundPayload): void {
        this.messageChannel.send('setWarmBackground', payload);
    }

    public isActionMenuChatShowing(payload: IActionMenuChatPayload): void {
        this.messageChannel.send('isActionMenuChatShowing', payload);
    }

    public connectToRoom(payload: IRoomConfigPayload): void {
        this.messageChannel.send('connectToRoom', payload);
    }

    public setChatClosedOverlay(payload: IShowChatClosedOverlayPayload): void {
        this.messageChannel.send('setChatClosedOverlay', payload);
    }

    public onPromoRequest(payload: IPromoRequestPayload): void {
        this.messageChannel.send('onPromoRequest', payload);
    }
}